public EventMessage decode(ParsableByteArray emsgData) {
  String schemeIdUri;
  String value;
  try {
    schemeIdUri = Assertions.checkNotNull(emsgData.readNullTerminatedString());
    value = Assertions.checkNotNull(emsgData.readNullTerminatedString());
  } catch (NullPointerException e) {
    throw new IllegalArgumentException("Input data is invalid", e);
  }
  long durationMs = emsgData.readUnsignedInt();
  long id = emsgData.readUnsignedInt();
  byte[] messageData = Arrays.copyOfRange(emsgData.data, emsgData.getPosition(), emsgData.limit());
  return new EventMessage(schemeIdUri, value, durationMs, id, messageData);
}
